// Object Destructuring & Renaming & Default Values
const user = { name: 'Alice', age: 25, job: 'Developer' };
const { name, age: userAge, location = 'Unknown' } = user;

console.log(name); // 'Alice'
console.log(userAge); // 25 (renamed from age)
console.log(location); // 'Unknown' (default value fallback)

// Array Destructuring & Rest parameter
const colors = ['red', 'green', 'blue', 'yellow'];
const [primary, secondary, ...otherColors] = colors;

console.log(primary); // 'red'
console.log(otherColors); // ['blue', 'yellow']

// Spread Operator for merging
const array1 = [1, 2];
const array2 = [3, 4];
const merged = [...array1, ...array2]; // [1, 2, 3, 4]
